package com.braseiro.pathfinder2e;

import org.json.JSONArray;
import org.json.JSONObject;
import java.text.Normalizer;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Sistema dedicado de guildas. Guildas são organizações persistentes ligadas
 * ao Mundo Vivo, mas não são reduzidas a uma facção genérica: preservam
 * hierarquia, membros, reputação, contratos, projetos, sedes, estoque,
 * tesouraria, relações e livro-caixa próprios.
 */
public final class GuildEngine {
    public static final String[] TYPES={"Aventureiros","Artesãos","Mercadores","Ladrões","Magos","Templo","Mercenários","Exploradores","Navegadores","Acadêmica","Política","Outra"};
    private final AppDb db;
    public GuildEngine(AppDb database){db=database;db.ensureGuildTables();}

    public long create(JSONObject specification)throws Exception{
        JSONObject clean=validateGuild(specification,true);long id=db.upsertGuildChecked(clean);ensureDefaultRanks(id,clean.optString("type"));db.syncGuildFactionChecked(id);return id;
    }
    public long update(JSONObject specification)throws Exception{
        JSONObject clean=validateGuild(specification,false);long id=db.upsertGuildChecked(clean);ensureDefaultRanks(id,clean.optString("type"));db.syncGuildFactionChecked(id);return id;
    }

    public int seedSuggestedGuilds(String tone)throws Exception{
        if(!db.listGuilds(1).isEmpty())return 0;String city=db.getSceneState().optString("location","o assentamento atual");
        JSONArray seeds=new JSONArray();
        seeds.put(new JSONObject().put("name","Liga dos Cartógrafos e Aventureiros").put("type","Aventureiros").put("description","Exploradores, guias e caçadores de contratos que registram rotas, perigos e descobertas.").put("charter","Proteger viajantes, cumprir contratos declarados e não ocultar perigos cartográficos.").put("headquarters",city).put("influence",42));
        seeds.put(new JSONObject().put("name","Confraria dos Ofícios Livres").put("type","Artesãos").put("description","Rede de ferreiros, curtidores, alquimistas, construtores e mestres de oficina.").put("charter","Qualidade, preço justo, aprendizado formal e proteção do segredo de ofício.").put("headquarters",city).put("influence",50));
        seeds.put(new JSONObject().put("name","Consórcio das Rotas Douradas").put("type","Mercadores").put("description","Mercadores, caravaneiros e financiadores que controlam crédito, armazéns e rotas.").put("charter","Honrar contratos, registrar dívidas e defender as rotas comerciais.").put("headquarters",city).put("influence",58));
        seeds.put(new JSONObject().put("name","Círculo da Chama Velada").put("type","Magos").put("description","Pesquisadores arcanos, copistas, professores e guardiões de artefatos perigosos.").put("charter","Conhecimento com responsabilidade, quarentena de riscos e registro de descobertas.").put("headquarters",city).put("influence",38));
        int created=0;for(int i=0;i<seeds.length();i++){create(seeds.getJSONObject(i));created++;}return created;
    }

    public void ensureNpcMembership(String npcName,String guildOrFaction)throws Exception{
        String name=clean(npcName,100),guildName=clean(guildOrFaction,120);if(name.length()==0||guildName.length()==0)return;
        JSONObject guild=db.findGuildByName(guildName);if(guild.length()==0)return;
        if(db.findGuildMember(guild.optLong("id"),"npc",0,name).length()==0){JSONObject rank=db.defaultGuildRank(guild.optLong("id"));db.addGuildMemberChecked(new JSONObject().put("guild_id",guild.optLong("id")).put("member_kind","npc").put("npc_name",name).put("rank_id",rank.optLong("id")).put("status","active").put("reputation",0).put("notes","Vínculo herdado do estado persistente do NPC."));}
    }

    public JSONArray promptView(int max){JSONArray out=new JSONArray();try{for(JSONObject guild:db.listGuilds(Math.max(1,max))){long gid=guild.optLong("id");JSONObject g=new JSONObject();g.put("id",gid).put("name",guild.optString("name")).put("type",guild.optString("type")).put("description",cut(guild.optString("description"),320)).put("charter",cut(guild.optString("charter"),360)).put("headquarters",guild.optString("headquarters")).put("treasury",guild.optDouble("treasury")).put("currency",guild.optString("currency","po")).put("party_reputation",guild.optInt("party_reputation")).put("influence",guild.optInt("influence")).put("current_plan",cut(guild.optString("current_plan"),320)).put("admission",parseLoose(guild.optString("admission_json","[]"))).put("benefits",parseLoose(guild.optString("benefits_json","[]"))).put("services",parseLoose(guild.optString("services_json","[]"))).put("rules",parseLoose(guild.optString("rules_json","[]"))).put("stock",parseLoose(guild.optString("stock_json","{}")));
            g.put("ranks",compact(db.listGuildRanks(gid),8,new String[]{"id","name","rank_order","requirements_json","benefits_json","permissions_json","dues_amount"}));
            g.put("members",compact(db.listGuildMembers(gid,"active",20),20,new String[]{"id","member_kind","character_id","hero_name","npc_name","rank_name","reputation","contribution","dues_due_day"}));
            g.put("contracts",compact(db.listGuildContracts(gid,"",12),12,new String[]{"id","title","description","issuer","status","requirements_json","reward_json","penalty_json","deadline_day","linked_quest_id"}));
            g.put("projects",compact(db.listGuildProjects(gid,"",12),12,new String[]{"id","title","description","kind","status","progress","goal","cost_json","result_json","location"}));
            g.put("sites",compact(db.listGuildSites(gid),12,new String[]{"id","name","site_type","location","hex_id","services_json","defenses_json","stock_json"}));
            g.put("relations",compact(db.listGuildRelations(gid),12,new String[]{"id","target_kind","target_guild_id","target_faction_id","target_name","relation","stance","treaties_json","notes"}));out.put(g);}}catch(Exception e){AppLog.e("GuildEngine","Falha ao montar contexto de guildas.",e);}return out;}


    public JSONObject validateUpdates(JSONObject envelope){if(envelope==null)envelope=new JSONObject();try{
        JSONArray source=envelope.optJSONArray("guild_updates"),clean=new JSONArray();
        if(source!=null)for(int i=0;i<source.length()&&clean.length()<20;i++){JSONObject update=source.optJSONObject(i);if(update==null)continue;String action=normalize(update.optString("action","update"));JSONObject x=new JSONObject();x.put("action",action.length()==0?"update":action);long id=update.optLong("id",update.optLong("guild_id",0));String name=clean(update.optString("name"),120);if(id<=0&&name.length()==0)continue;if(id>0)x.put("id",id);if(name.length()>0)x.put("name",name);
            if("create".equals(action)||"update".equals(action)){for(String key:new String[]{"type","description","charter","headquarters","currency","current_plan","dues_policy_json","admission_json","benefits_json","services_json","rules_json","stock_json"})if(update.has(key))x.put(key,cut(String.valueOf(update.opt(key)),key.endsWith("_json")?5000:1200));for(String key:new String[]{"treasury","party_reputation","influence","active"})if(update.has(key))x.put(key,update.opt(key));}
            else if("member_add".equals(action)){x.put("member_kind",normalize(update.optString("member_kind","npc"))).put("character_id",update.optLong("character_id",0)).put("npc_name",clean(update.optString("npc_name"),100)).put("rank_id",update.optLong("rank_id",0)).put("status",normalize(update.optString("status","active"))).put("reputation",clamp(update.optInt("reputation"),-100,100)).put("notes",cut(update.optString("notes"),600));}
            else if("contract_create".equals(action)){x.put("title",clean(update.optString("title"),160)).put("description",cut(update.optString("description"),1800)).put("issuer",clean(update.optString("issuer"),120)).put("requirements_json",jsonArrayOrObjectText(update.opt("requirements_json"),"{}")).put("reward_json",jsonArrayOrObjectText(update.opt("reward_json"),"{}")).put("penalty_json",jsonArrayOrObjectText(update.opt("penalty_json"),"{}")).put("deadline_day",Math.max(0,update.optInt("deadline_day")));}
            else if("project_create".equals(action)){x.put("title",clean(update.optString("title"),160)).put("description",cut(update.optString("description"),1800)).put("kind",clean(update.optString("kind"),80)).put("goal",Math.max(1,update.optInt("goal",100))).put("progress_per_day",Math.max(.1d,update.optDouble("progress_per_day",5d))).put("cost_json",jsonArrayOrObjectText(update.opt("cost_json"),"{}")).put("result_json",jsonArrayOrObjectText(update.opt("result_json"),"{}")).put("location",clean(update.optString("location"),180));}
            else if("rank_create".equals(action)){x.put("rank_name",clean(update.optString("rank_name",update.optString("title")),120)).put("rank_order",Math.max(0,update.optInt("rank_order"))).put("requirements_json",jsonArrayOrObjectText(update.opt("requirements_json"),"{}")).put("benefits_json",jsonArrayOrObjectText(update.opt("benefits_json"),"[]")).put("permissions_json",jsonArrayOrObjectText(update.opt("permissions_json"),"[]")).put("dues_amount",Math.max(0d,update.optDouble("dues_amount")));}
            else if("member_reputation".equals(action)){x.put("member_id",update.optLong("member_id",0)).put("reputation_delta",clamp(update.optInt("reputation_delta"),-100,100)).put("contribution_delta",Math.max(-100000d,Math.min(100000d,update.optDouble("contribution_delta",0))));}
            else if("contract_status".equals(action)){x.put("contract_id",update.optLong("contract_id",0)).put("status",normalize(update.optString("status"))).put("owner_character_id",Math.max(0,update.optLong("owner_character_id",0)));}
            else if("site_create".equals(action)){x.put("site_name",clean(update.optString("site_name",update.optString("title")),160)).put("site_type",clean(update.optString("site_type","sede"),80)).put("location",clean(update.optString("location"),180)).put("hex_id",clean(update.optString("hex_id"),80)).put("services_json",jsonArrayOrObjectText(update.opt("services_json"),"[]")).put("defenses_json",jsonArrayOrObjectText(update.opt("defenses_json"),"{}")).put("stock_json",jsonArrayOrObjectText(update.opt("stock_json"),"{}"));}
            else if("relation_update".equals(action)){x.put("target_kind",normalize(update.optString("target_kind","guild"))).put("target_guild_id",Math.max(0,update.optLong("target_guild_id",0))).put("target_faction_id",Math.max(0,update.optLong("target_faction_id",0))).put("target_name",clean(update.optString("target_name"),160)).put("relation",clamp(update.optInt("relation"),-100,100)).put("stance",normalize(update.optString("stance","neutral"))).put("treaties_json",jsonArrayOrObjectText(update.opt("treaties_json"),"[]")).put("notes",cut(update.optString("notes"),1200));}
            else if("ledger".equals(action)){x.put("entry_type",normalize(update.optString("entry_type","adjustment"))).put("amount",update.optDouble("amount")).put("currency",clean(update.optString("currency","po"),20)).put("description",cut(update.optString("description"),600)).put("actor",clean(update.optString("actor"),120));}
            boolean validAction=knownAction(action);
            if("member_add".equals(action))validAction=("hero".equals(x.optString("member_kind"))&&x.optLong("character_id")>0)||("npc".equals(x.optString("member_kind"))&&x.optString("npc_name").trim().length()>0);
            else if("member_reputation".equals(action))validAction=x.optLong("member_id")>0;
            else if("contract_create".equals(action)||"project_create".equals(action))validAction=x.optString("title").trim().length()>0;
            else if("rank_create".equals(action))validAction=x.optString("rank_name").trim().length()>0;
            else if("contract_status".equals(action))validAction=x.optLong("contract_id")>0&&allowedContractStatus(x.optString("status"));
            else if("site_create".equals(action))validAction=x.optString("site_name").trim().length()>0;
            else if("relation_update".equals(action))validAction=x.optString("target_name").trim().length()>0;
            else if("ledger".equals(action))validAction=Math.abs(x.optDouble("amount",0d))>.000001d;
            if(validAction)clean.put(x);
        }envelope.put("guild_updates",clean).put("_guild_validation",new JSONObject().put("valid",true).put("count",clean.length()));
    }catch(Exception failure){try{envelope.put("guild_updates",new JSONArray()).put("_guild_validation",new JSONObject().put("valid",false).put("fail_closed",true).put("error",String.valueOf(failure.getMessage())));}catch(Exception ignored){AppLog.ignored("GuildEngine","Falha ao registrar diagnóstico.",ignored);}AppLog.e("GuildEngine","Atualizações de guilda bloqueadas.",failure);}return envelope;}

    public void applyUpdates(JSONObject envelope)throws Exception{JSONArray updates=envelope==null?null:envelope.optJSONArray("guild_updates");if(updates==null)return;for(int i=0;i<updates.length();i++){JSONObject u=updates.optJSONObject(i);if(u==null)continue;String action=u.optString("action","update");long id=resolveGuildId(u);if("create".equals(action)){create(u);continue;}if(id<=0)continue;if("update".equals(action)){u.put("id",id);update(u);}else if("member_add".equals(action)){u.put("guild_id",id);db.addGuildMemberChecked(u);if("npc".equals(u.optString("member_kind")))ensureNpcMembership(u.optString("npc_name"),db.getGuild(id).optString("name"));}else if("member_reputation".equals(action)){db.adjustGuildMemberReputationChecked(u.optLong("member_id"),u.optInt("reputation_delta"),u.optDouble("contribution_delta"));}else if("rank_create".equals(action)){db.addGuildRankChecked(new JSONObject().put("guild_id",id).put("name",u.optString("rank_name")).put("rank_order",u.optInt("rank_order")).put("requirements_json",u.optString("requirements_json","{}")).put("benefits_json",u.optString("benefits_json","[]")).put("permissions_json",u.optString("permissions_json","[]")).put("dues_amount",u.optDouble("dues_amount")));}else if("contract_create".equals(action)){u.put("guild_id",id);db.addGuildContractChecked(u);}else if("contract_status".equals(action)){String status=u.optString("status");if("accepted".equals(status))db.acceptGuildContractChecked(u.optLong("contract_id"),u.optLong("owner_character_id"));else if("completed".equals(status))db.completeGuildContractChecked(u.optLong("contract_id"));else db.updateGuildContractStatus(u.optLong("contract_id"),status,new JSONObject().put("updated_by","master_reviewed"));}else if("project_create".equals(action)){u.put("guild_id",id);db.addGuildProjectChecked(u);}else if("site_create".equals(action)){db.addGuildSiteChecked(new JSONObject().put("guild_id",id).put("name",u.optString("site_name")).put("site_type",u.optString("site_type")).put("location",u.optString("location")).put("hex_id",u.optString("hex_id")).put("services_json",u.optString("services_json","[]")).put("defenses_json",u.optString("defenses_json","{}")).put("stock_json",u.optString("stock_json","{}")));}else if("relation_update".equals(action)){u.put("guild_id",id);db.upsertGuildRelationChecked(u);}else if("ledger".equals(action)){u.put("guild_id",id);db.addGuildLedgerEntryChecked(u);}}}


    public JSONObject previewTick(double hours,int day){JSONObject out=new JSONObject();JSONArray actions=new JSONArray();try{for(JSONObject guild:db.listGuilds(100)){if(guild.optInt("active",1)!=1)continue;long gid=guild.optLong("id");for(JSONObject project:db.listGuildProjects(gid,"active",100)){double progress=project.optDouble("progress",0),goal=Math.max(1d,project.optDouble("goal",100)),rate=Math.max(.1d,project.optDouble("progress_per_day",5d));double next=Math.min(goal,progress+hours/24d*rate);if(next>progress)actions.put(new JSONObject().put("kind","project_progress").put("guild_id",gid).put("project_id",project.optLong("id")).put("progress_before",progress).put("progress_after",next).put("completed",next>=goal));}
            for(JSONObject contract:db.listGuildContracts(gid,"",100)){String status=contract.optString("status");int deadline=contract.optInt("deadline_day",0);if(("open".equals(status)||"accepted".equals(status))&&deadline>0&&day>deadline)actions.put(new JSONObject().put("kind","contract_expired").put("guild_id",gid).put("contract_id",contract.optLong("id")).put("status_before",status));}
            for(JSONObject member:db.listGuildMembers(gid,"active",1000)){int paid=member.optInt("dues_paid_day",member.optInt("joined_day",1)),due=Math.max(member.optInt("joined_day",1)+30,paid+30),notice=member.optInt("last_dues_notice_day",0);JSONObject rank=db.getGuildMember(member.optLong("id"));double dues=rank.optDouble("rank_dues_amount",0);if(dues>0&&day>=due&&notice<due)actions.put(new JSONObject().put("kind","dues_due").put("guild_id",gid).put("member_id",member.optLong("id")).put("due_day",due).put("notice_day",day).put("amount",dues).put("currency",guild.optString("currency","po")));}
        }out.put("hours",hours).put("day",day).put("actions",actions).put("preview_only",true);}catch(Exception e){try{out.put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("GuildEngine","Falha ao registrar diagnóstico.",ignored);}}return out;}

    public void applyTick(JSONObject preview)throws Exception{if(preview==null||!preview.optBoolean("preview_only",false))return;JSONArray actions=preview.optJSONArray("actions");if(actions!=null)for(int i=0;i<actions.length();i++)db.applyGuildSimulationActionChecked(actions.optJSONObject(i));preview.put("preview_only",false).put("committed",true);}

    public JSONObject diagnostic(){JSONObject out=new JSONObject();try{out.put("guilds",db.listGuilds(10000).size()).put("members",db.countGuildRows("guild_members")).put("ranks",db.countGuildRows("guild_ranks")).put("contracts",db.countGuildRows("guild_contracts")).put("projects",db.countGuildRows("guild_projects")).put("sites",db.countGuildRows("guild_sites")).put("ledger_entries",db.countGuildRows("guild_ledger")).put("relations",db.countGuildRows("guild_relations")).put("complete",true);}catch(Exception e){try{out.put("complete",false).put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("GuildEngine","Falha ao registrar diagnóstico.",ignored);}}return out;}

    private static JSONArray compact(List<JSONObject> rows,int max,String[] keys){JSONArray out=new JSONArray();if(rows==null)return out;for(int i=0;i<rows.size()&&i<max;i++){JSONObject source=rows.get(i),item=new JSONObject();try{for(String key:keys)if(source.has(key)){Object value=source.opt(key);if(key.endsWith("_json")&&value instanceof String)item.put(key,parseLoose(String.valueOf(value)));else item.put(key,value);}out.put(item);}catch(Exception ignored){AppLog.ignored("GuildEngine","Registro compacto de guilda ignorado.",ignored);}}return out;}
    private static Object parseLoose(String raw){try{String safe=raw==null?"":raw.trim();if(safe.startsWith("["))return new JSONArray(safe);if(safe.startsWith("{"))return new JSONObject(safe);}catch(Exception ignored){AppLog.ignored("GuildEngine","JSON editorial inválido ignorado.",ignored);}return raw==null?"":raw;}

    private void ensureDefaultRanks(long guildId,String type)throws Exception{if(guildId<=0||!db.listGuildRanks(guildId).isEmpty())return;String[] names;if("Magos".equals(type))names=new String[]{"Iniciado","Adepto","Mestre","Arquimago"};else if("Ladrões".equals(type))names=new String[]{"Contato","Operador","Tenente","Mestre da Guilda"};else if("Templo".equals(type))names=new String[]{"Noviço","Acólito","Sacerdote","Hierofante"};else if("Mercadores".equals(type))names=new String[]{"Associado","Negociante","Feitor","Mestre do Consórcio"};else names=new String[]{"Aspirante","Membro","Veterano","Mestre da Guilda"};for(int i=0;i<names.length;i++)db.addGuildRankChecked(new JSONObject().put("guild_id",guildId).put("name",names[i]).put("rank_order",i).put("requirements_json",new JSONObject().put("reputation",i*25)).put("benefits_json",new JSONArray()).put("permissions_json",new JSONArray()).put("dues_amount",i==0?0:Math.max(1,i*2)));}
    private JSONObject validateGuild(JSONObject source,boolean creating)throws Exception{if(source==null)throw new IllegalArgumentException("Dados da guilda ausentes.");JSONObject out=new JSONObject();long id=source.optLong("id",source.optLong("guild_id",0));if(id>0)out.put("id",id);String name=clean(source.optString("name"),120);if(name.length()<3)throw new IllegalArgumentException("Informe um nome de guilda com pelo menos 3 caracteres.");out.put("name",name);String type=clean(source.optString("type","Outra"),60);out.put("type",knownType(type)?type:"Outra");out.put("description",cut(source.optString("description"),1800)).put("charter",cut(source.optString("charter"),1800)).put("headquarters",clean(source.optString("headquarters"),180)).put("currency",clean(source.optString("currency","po"),20));out.put("treasury",Math.max(0d,source.optDouble("treasury",0d))).put("party_reputation",clamp(source.optInt("party_reputation"),-100,100)).put("influence",clamp(source.optInt("influence",25),0,100)).put("active",source.has("active")?source.optBoolean("active",true):true).put("current_plan",cut(source.optString("current_plan"),1200));for(String key:new String[]{"dues_policy_json","admission_json","benefits_json","services_json","rules_json","stock_json"})out.put(key,jsonArrayOrObjectText(source.opt(key),key.equals("stock_json")?"{}":"[]"));return out;}
    private long resolveGuildId(JSONObject update){long id=update.optLong("id",update.optLong("guild_id",0));if(id>0)return id;return db.findGuildByName(update.optString("name")).optLong("id",0);}
    private static boolean knownAction(String action){return "create".equals(action)||"update".equals(action)||"member_add".equals(action)||"member_reputation".equals(action)||"rank_create".equals(action)||"contract_create".equals(action)||"contract_status".equals(action)||"project_create".equals(action)||"site_create".equals(action)||"relation_update".equals(action)||"ledger".equals(action);}
    private static boolean allowedContractStatus(String status){return "open".equals(status)||"accepted".equals(status)||"completed".equals(status)||"cancelled".equals(status)||"failed".equals(status)||"expired".equals(status);}
    private static boolean knownType(String t){for(String v:TYPES)if(v.equalsIgnoreCase(t))return true;return false;}
    private static String jsonArrayOrObjectText(Object value,String fallback){if(value==null||value==JSONObject.NULL)return fallback;if(value instanceof JSONObject||value instanceof JSONArray)return value.toString();String s=String.valueOf(value).trim();if(s.startsWith("{")||s.startsWith("["))return s;return fallback;}
    private static int clamp(int v,int min,int max){return Math.max(min,Math.min(max,v));}
    private static String clean(String v,int max){String s=v==null?"":v.trim().replaceAll("[\\r\\n]+"," ").replaceAll("\\s+"," ");return s.length()<=max?s:s.substring(0,max);}
    private static String cut(String v,int max){String s=v==null?"":v.trim();return s.length()<=max?s:s.substring(0,max)+"…";}
    private static String normalize(String value){String n=Normalizer.normalize(value==null?"":value.toLowerCase(new Locale("pt","BR")),Normalizer.Form.NFD).replaceAll("\\p{M}","");return n.replaceAll("[^a-z0-9_]+","_").replaceAll("_+","_").replaceAll("^_|_$","");}
}
